"use client";
import { useState, type FormEvent } from "react";
import { Mail, Clock3, MessageCircle, Send } from "lucide-react";
import { api, errorMessage } from "@/lib/api";
import { PageHeader } from "@/components/ui";
export default function ContactPage() {
  const [form, setForm] = useState({ name: "", email: "", subject: "", message: "" }); const [error, setError] = useState(""); const [sent, setSent] = useState(false);
  async function submit(e: FormEvent) { e.preventDefault(); if (form.name.trim().length < 2 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email.trim()) || form.subject.trim().length < 3 || form.message.trim().length < 20) { setError("Add your name, a valid email, a subject, and a message of at least 20 characters."); return; } try { await api("/contact-messages", { method: "POST", body: JSON.stringify(form) }); setError(""); setSent(true); } catch (error) { setError(errorMessage(error)); } }
  return <div className="container-page py-12"><PageHeader title="Let's talk" eyebrow="Contact Learnova" description="Have a question about your learning journey? We would love to help." /><div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_350px]"><form className="panel space-y-5 p-6 md:p-8" onSubmit={submit} noValidate>{[["Name", "name"], ["Email", "email"], ["Subject", "subject"]].map(([label, field]) => <label className="block" key={field}><span className="field-label">{label}</span><input className="field" type={field === "email" ? "email" : "text"} value={form[field as "name" | "email" | "subject"]} onChange={e => { setForm({ ...form, [field]: e.target.value }); setSent(false); }} /></label>)}<label className="block"><span className="field-label">Message</span><textarea className="field min-h-40" value={form.message} onChange={e => { setForm({ ...form, message: e.target.value }); setSent(false); }} placeholder="How can we help?" /></label>{error && <p className="form-error" role="alert">{error}</p>}{sent && <p className="notice" role="status">Your message has been saved for the support team.</p>}<button className="btn-primary"><Send size={17} />Send Message</button></form><aside className="space-y-5">{[{ title: "Email", icon: Mail, text: "hello@learnova.example" }, { title: "Student support", icon: MessageCircle, text: "Questions about courses, assignments, or your account." }, { title: "Office hours", icon: Clock3, text: "Monday–Friday, 9:00 AM–5:00 PM (Sri Lanka time)." }].map(({ title, icon: Icon, text }) => <div className="panel p-6" key={title}><Icon className="text-blue-400" size={25} /><h2 className="mt-4 font-bold">{title}</h2><p className="mt-3 break-words text-sm leading-7 text-slate-400">{text}</p></div>)}<p className="px-2 text-xs leading-6 text-slate-400">Contact details and office hours are examples for this frontend preview.</p></aside></div></div>;
}
